const ELEMENT_PROP_KEYS = new Set(["theme","label","generations","fontWeight","pause","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  label: "×2 every week",
  generations: 6,
  fontWeight: 300,
  pause: 4,
  accent: "#3B5BFD",
  fontFamily: "Sora",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type CellDivideElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof CellDivideBase>;

const CellDivideInner = forwardRef<
  HTMLDivElement,
  CellDivideElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<CellDivide>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <CellDivideBase
          {...(componentProps as unknown as ComponentProps<typeof CellDivideBase>)}
        />
      </div>
    </Sequence>
  );
});

export const CellDivide = Interactive.withSchema({
  Component: CellDivideInner,
  componentName: "<CellDivide>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
